using System.Reflection;
using System.Security.Cryptography;
using System.Text;
using vsc.ClassMappingsGenerator.Attributes;

namespace vsc.ClassMappingsGenerator.Mappings
{
    /// <summary>
    /// Generated by Copilot: Extension methods for <see cref="MemberInfo"/> to simplify type checks and metadata access.
    /// </summary>
    public static class MemberInfoExtensions
    {
        /// <summary>
        /// Generated by Copilot: Gets the data type of a member (property, field, or method).
        /// </summary>
        public static Type? GetMemberDataType(this MemberInfo member)
            => member switch
            {
                PropertyInfo property => property.PropertyType,
                FieldInfo field => field.FieldType,
                MethodInfo method => method.ReturnType,
                _ => null
            };

        /// <summary>
        /// Generated by Copilot: Determines if the member is a basic type (primitive, string, etc.).
        /// </summary>
        public static bool MemberIsBasic(this MemberInfo? member)
            => member != null && (
                (member is FieldInfo field && field.FieldType.IsBasicType()) ||
                (member is PropertyInfo property && property.PropertyType.IsBasicType())
            );

        /// <summary>
        /// Generated by Copilot: Determines if the member is a class (excluding collections).
        /// </summary>
        public static bool MemberIsClass(this MemberInfo? member)
            => member != null &&
                (
                    (member is FieldInfo field && field.FieldType.IsClass) ||
                    (member is PropertyInfo property && property.PropertyType.IsClass)
                ) &&
                !member.MemberIsIEnumerable();

        /// <summary>
        /// Generated by Copilot: Determines if the member is a List.
        /// </summary>
        public static bool MemberIsList(this MemberInfo? member)
            => member != null && (
                (member is FieldInfo field && field.FieldType.IsList()) ||
                (member is PropertyInfo property && property.PropertyType.IsList())
            );

        /// <summary>
        /// Generated by Copilot: Determines if the member is an ICollection.
        /// </summary>
        public static bool MemberIsICollection(this MemberInfo? member)
            => member != null && (
                (member is FieldInfo field && field.FieldType.IsICollection()) ||
                (member is PropertyInfo property && property.PropertyType.IsICollection())
            );

        /// <summary>
        /// Generated by Copilot: Determines if the member is an IEnumerable.
        /// </summary>
        public static bool MemberIsIEnumerable(this MemberInfo? member)
            => member != null && (
                (member is FieldInfo field && field.FieldType.IsIEnumerable()) ||
                (member is PropertyInfo property && property.PropertyType.IsIEnumerable())
            );

        /// <summary>
        /// Generated by Copilot: Determines if the member is a method.
        /// </summary>
        public static bool MemberIsMethod(this MemberInfo? member)
            => member is MethodInfo;
    }

    /// <summary>
    /// Generated by Copilot: Compares <see cref="MemberInfo"/> objects by name and declaring type.
    /// </summary>
    public class MemberInfoNameTypeComparer : IEqualityComparer<MemberInfo>
    {
        /// <summary>
        /// Generated by Copilot: Checks equality by member name and declaring type.
        /// </summary>
        public bool Equals(MemberInfo? x, MemberInfo? y)
        {
            if (x == null || y == null)
                return false;

            return x.Name == y.Name && x.DeclaringType == y.DeclaringType;
        }

        /// <summary>
        /// Generated by Copilot: Generates a hash code based on member name and declaring type.
        /// </summary>
        public int GetHashCode(MemberInfo obj)
        {
            // Generated by Copilot: Use MD5 hash of name + declaring type for stable hash code.
            using (MD5 md5 = MD5.Create())
            {
                string input = obj.Name + (obj.DeclaringType?.FullName ?? string.Empty);
                byte[] bytes = md5.ComputeHash(Encoding.UTF8.GetBytes(input));
                int hash = BitConverter.ToInt32(bytes, 0);
                // Ensure non-negative hash code
                return hash == int.MinValue ? 0 : Math.Abs(hash);
            }
        }
    }
}
